// Artwork is generated by image_gen. This script only resamples and lays out the review.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const sharp=require(process.env.RL_SHARP_MODULE||'sharp');
const out=__dirname,root=path.resolve(out,'../../..'),base=path.resolve(out,'..');
const read=f=>JSON.parse(fs.readFileSync(f,'utf8').replace(/^\uFEFF/,''));
const hash=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const rel=f=>path.relative(root,f).replaceAll('\\','/');
const ledger=read(path.join(base,'skill-icon-acceptance.json'));
const active=ledger.compact_accepted.find(c=>c.id==='M03');
if(active.variant!=='M03-C02'||active.number!==8)throw Error('Unexpected active M03');
const protectionFile=path.join(out,'protected-hashes.json');
if(!fs.existsSync(protectionFile)) {
  const protectedFiles=read(path.join(base,'skill-icon-review-36/protected-hashes.json'));
  const collect=dir=>{for(const e of fs.readdirSync(dir,{withFileTypes:true})) {
    const f=path.join(dir,e.name);if(e.isDirectory())collect(f);else protectedFiles.push({file:rel(f),sha256:hash(f)});
  }};
  collect(path.join(base,'skill-icon-review-36'));
  fs.writeFileSync(protectionFile,JSON.stringify(protectedFiles,null,2)+'\n');
}
const protectedFiles=read(protectionFile);
const verify=()=>{for(const f of protectedFiles)if(hash(path.resolve(root,f.file))!==f.sha256)throw Error('Protected file changed: '+f.file);};
const svgImage=(f,x,y,s)=>`<image x="${x}" y="${y}" width="${s}" height="${s}" href="data:image/png;base64,${fs.readFileSync(f).toString('base64')}"/>`;
async function main(){
  verify();
  const source=read(path.join(out,'sources.json'));
  const master=path.join(out,'M03-C05-master.png');fs.copyFileSync(source.source_path,master);
  const files={};
  for(const s of [192,128,64,32,24]){
    const file=`M03-C05-${s}.png`,dest=path.join(out,file);
    await sharp(master).resize(s,s,{fit:'fill',kernel:'lanczos3'}).png().toFile(dest);
    const meta=await sharp(dest).metadata();if(meta.width!==s||meta.height!==s)throw Error('Wrong native size');
    files[s]={file,sha256:hash(dest),width:s,height:s};
  }
  const candidate={id:'M03',number:8,variant:'M03-C05',kind:'compact',title:'Puissance métamorphe',visual_status:'pending',revision_scope:'Simple symbol of four claw scratches, without anatomical hand',files,master:{file:path.basename(master),sha256:hash(master)}};
  const review={review_id:'SKILLS-IC37',user_feedback:'bon je n’arrive pas à aimer il faudrait plutôt une icône je pense',candidates:[candidate],active_variant:active.variant,previous_proposals_not_approved:['M03-C03','M03-C04'],IC34_candidates_still_pending:['TR61-C01','TR63-C01','TR64-C01','TR65-C01'],protected_hashes:protectedFiles,generation:{tool:'image_gen.imagegen',use_case:'stylized-concept',source_path:source.source_path,source_sha256:hash(source.source_path),prompt_file:'prompts/M03-C05.txt',drawing_edits_by_code:false}};
  fs.writeFileSync(path.join(out,'review.json'),JSON.stringify(review,null,2)+'\n');
  const native=[32,64,24].map(s=>`<div><img src="${files[s].file}" width="${s}" height="${s}" alt="Quatre griffures ${s} px"><span>${s} px</span></div>`).join('');
  fs.writeFileSync(path.join(out,'index.html'),`<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IC37 · Puissance métamorphe</title><style>*{box-sizing:border-box}body{margin:0;padding:28px;background:#0b1017;color:#e1e7ec;font:15px Segoe UI,Arial}main{max-width:730px;margin:auto}h1{font-size:26px;margin:8px 0 14px}p{line-height:1.6;color:#a6b6c5}small{color:#b6a8ff}article{padding:24px;background:#111923;border:1px solid #3a4654;border-radius:10px;max-width:480px;margin:24px auto;text-align:center}h2{font-size:19px;margin:0 0 24px}.large{display:grid;justify-items:center;gap:10px}.native{display:flex;justify-content:center;gap:48px;align-items:end;margin:28px 0 22px}.native>div{display:grid;justify-items:center;gap:10px}span{color:#a6b6c5;font-size:12px}img{display:block;max-width:none}footer{font-size:12px;line-height:1.8;color:#a6b6c5}a{color:#d7cef4}@media(max-width:480px){body{padding:16px}.native{gap:32px}}</style><main><small>SKILLS-IC37 · ICÔNE 8 · M03-C05</small><h1>Puissance métamorphe · symbole</h1><p>Quatre marques de griffes. Un symbole simple, avec un accent occulte discret, pensé pour la lecture à 32 px.</p><article><h2>8 · Puissance métamorphe</h2><div class="large"><img src="${files[128].file}" width="128" height="128" alt="Symbole de quatre griffures"><span>128 px · détail</span></div><div class="native">${native}</div><small>M03-C05 · proposition</small></article><p>Nouvelle icône à valider.</p><footer>Petites vues à taille réelle, sans agrandissement.<br>Textes, effets et illustration détaillée inchangés. La banque conserve le dernier dessin validé.<br><a href="prompts/M03-C05.txt">Prompt · Imagegen intégré</a> · <a href="../skill-icon-review-36/index.html">Essai précédent</a> · <a href="../skill-icon-review-34/index.html">Transformations à examiner</a></footer></main></html>`);
  const parts=['<rect width="540" height="420" fill="#0b1017"/>','<text x="24" y="34" font-size="21" fill="#e1e7ec">8 · Puissance métamorphe</text>','<text x="24" y="61" font-size="13" fill="#b6a8ff">M03-C05 · symbole de quatre griffures</text>',svgImage(path.join(out,files[128].file),206,84,128)];
  for(const[s,x]of[[32,146],[64,246],[24,386]])parts.push(svgImage(path.join(out,files[s].file),x,280-s,s),`<text x="${x+s/2}" y="305" text-anchor="middle" font-size="13" fill="#a6b6c5">${s} px</text>`);
  parts.push('<text x="24" y="363" font-size="13" fill="#a6b6c5">Vues natives · nouvelle proposition</text>','<text x="24" y="395" font-size="12" fill="#a6b6c5">En attente de validation visuelle.</text>');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="540" height="420"><g font-family="Segoe UI,Arial">${parts.join('')}</g></svg>`;
  fs.writeFileSync(path.join(out,'native-review-board.svg'),svg);await sharp(Buffer.from(svg)).png().toFile(path.join(out,'native-review-board.png'));
  verify();
  fs.writeFileSync(path.join(out,'validation.json'),JSON.stringify({review_id:review.review_id,exports:[192,128,64,32,24],protected_files_preserved:protectedFiles.length,active_bank_unchanged:true,previous_drawings_archived:true,IC34_candidates_unchanged:true,visual_inspection:'Pending',drawing_edits_by_code:false},null,2)+'\n');
  fs.writeFileSync(path.join(out,'README.md'),'# IC37 · Puissance métamorphe, symbole\n\nIcône 8, variante M03-C05 : quatre marques de griffes sans main anatomique, à la demande du joueur qui préfère une icône. Les essais M03-C03 et C04 sont conservés mais ne sont pas validés.\n\nImagegen intégré ; master copié dans le dossier de revue, prompt exact dans prompts/M03-C05.txt. Redimensionnement Lanczos uniquement. Aucun dessin par code. Vues natives 32, 64 et 24 px, détail 128 px.\n\nNouvelle proposition non intégrée avant validation. Textes, effets, illustration détaillée et autres dessins préservés.\n');
  console.log(JSON.stringify({review:review.review_id,variant:candidate.variant,protected_files:protectedFiles.length}));
}
main().catch(e=>{console.error(e);process.exitCode=1;});
